#include "g2m/layer/field_rules.h"
#include "g2m/core/hash.h"
#include "strict_json.h"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <set>

namespace g2m {
namespace {
using json = nlohmann::json;
using strict::Reader;
// const unsigned char kFieldRulesDe[]: the bytes of data/field_rules/de.json, generated by CMake.
#include "field_rules_de.inc"

bool read_match(Reader& rd, const json& o, const std::string& path, FieldTagMatch& out) {
    if (!rd.text(o, path, "key", out.key)) return false;
    if (out.key.empty()) return rd.fail(path + ".key must not be empty");
    const auto* values = rd.field(o, path, "values");
    if (!values) return false;
    if (!values->is_array() || values->empty()) return rd.fail(path + ".values must be a non-empty array");
    for (const auto& v : *values) {
        if (!v.is_string() || v.get<std::string>().empty()) return rd.fail(path + ".values entries must be non-empty strings");
        out.values.push_back(v.get<std::string>());
    }
    std::sort(out.values.begin(), out.values.end());
    if (std::adjacent_find(out.values.begin(), out.values.end()) != out.values.end()) return rd.fail(path + ".values has a duplicate");
    return true;
}
} // namespace

bool field_tag_matches(const FieldTagMatch& match, std::string_view value) {
    if (std::binary_search(match.values.begin(), match.values.end(), std::string("*"))) return value != "no";
    return std::binary_search(match.values.begin(), match.values.end(), std::string(value));
}

std::int32_t FieldRules::max_half_width_mm() const {
    std::int32_t m = 0;
    for (const auto& s : splitters) m = std::max(m, s.half_width_mm);
    return m;
}
int FieldRules::landuse_code(std::string_view value) const {
    const auto it = std::lower_bound(landuse.begin(), landuse.end(), value,
        [](const FieldLanduseRule& r, std::string_view v) { return r.value < v; });
    return it != landuse.end() && it->value == value ? it->code : -1;
}

Result<FieldRules> load_field_rules(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "field rules: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "field rules: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "landuse", "skip", "splitters", "obstacles", "raster", "block", "obstacle_share_cap_percent",
            "single_piece_keep_percent", "sliver", "simplify", "plausible", "match", "sources"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.field_rules/1") return make_error(ErrorCode::Unsupported, "field rules: format '" + format + "'");
    FieldRules out;

    const auto* landuse = rd.field(j, "root", "landuse");
    if (!landuse || !rd.object(*landuse, "landuse")) return fail();
    if (landuse->empty()) { rd.fail("landuse must not be empty"); return fail(); }
    std::set<int> codes;
    for (auto it = landuse->begin(); it != landuse->end(); ++it) {
        if (!it.value().is_number_integer() || it.value().get<std::int64_t>() < 0 || it.value().get<std::int64_t>() > 255) {
            rd.fail("landuse." + it.key() + " must be an integer in [0, 255]"); return fail();
        }
        const int code = static_cast<int>(it.value().get<std::int64_t>());
        if (!codes.insert(code).second) { rd.fail("landuse: duplicate code " + std::to_string(code)); return fail(); }
        out.landuse.push_back({it.key(), static_cast<std::uint8_t>(code)});
    }
    std::sort(out.landuse.begin(), out.landuse.end(), [](const auto& a, const auto& b) { return a.value < b.value; });

    const auto* skip = rd.field(j, "root", "skip");
    if (!skip || !skip->is_array()) { rd.fail("skip must be an array"); return fail(); }
    for (std::size_t i = 0; i < skip->size(); ++i) {
        const std::string path = "skip[" + std::to_string(i) + "]";
        const auto& e = (*skip)[i];
        FieldTagMatch m;
        if (!rd.keys(e, path, {"key", "values"}) || !read_match(rd, e, path, m)) return fail();
        out.skip.push_back(std::move(m));
    }

    const auto* splitters = rd.field(j, "root", "splitters");
    if (!splitters || !splitters->is_array() || splitters->empty()) { rd.fail("splitters must be a non-empty array"); return fail(); }
    std::set<std::string> names;
    for (std::size_t i = 0; i < splitters->size(); ++i) {
        const std::string path = "splitters[" + std::to_string(i) + "]";
        const auto& e = (*splitters)[i];
        FieldSplitterRule r;
        if (!rd.keys(e, path, {"name", "key", "values", "half_width_mm"}) || !rd.text(e, path, "name", r.name) ||
            !read_match(rd, e, path, r.match) || !rd.integer(e, path, "half_width_mm", 100, 20000, r.half_width_mm)) return fail();
        if (!names.insert(r.name).second) { rd.fail(path + ": duplicate name '" + r.name + "'"); return fail(); }
        out.splitters.push_back(std::move(r));
    }
    const auto* obstacles = rd.field(j, "root", "obstacles");
    if (!obstacles || !obstacles->is_array()) { rd.fail("obstacles must be an array"); return fail(); }
    for (std::size_t i = 0; i < obstacles->size(); ++i) {
        const std::string path = "obstacles[" + std::to_string(i) + "]";
        const auto& e = (*obstacles)[i];
        FieldObstacleRule r;
        if (!rd.keys(e, path, {"name", "key", "values"}) || !rd.text(e, path, "name", r.name) || !read_match(rd, e, path, r.match)) return fail();
        if (!names.insert(r.name).second) { rd.fail(path + ": duplicate name '" + r.name + "'"); return fail(); }
        out.obstacles.push_back(std::move(r));
    }

    const auto* raster = rd.field(j, "root", "raster");
    if (!raster || !rd.keys(*raster, "raster", {"cell_mm", "max_cells"}) ||
        !rd.integer(*raster, "raster", "cell_mm", 200, 4000, out.cell_mm) ||
        !rd.integer(*raster, "raster", "max_cells", 10000, 64000000, out.max_cells)) return fail();
    if (out.cell_mm % 2 != 0) { rd.fail("raster.cell_mm must be even (cell centres are whole millimetres)"); return fail(); }
    const auto* block = rd.field(j, "root", "block");
    if (!block || !rd.keys(*block, "block", {"max_extent_m", "max_cover_tiles"}) ||
        !rd.integer(*block, "block", "max_extent_m", 100, 8000, out.block_max_extent_m) ||
        !rd.integer(*block, "block", "max_cover_tiles", 1, 64, out.block_max_cover_tiles)) return fail();
    if (!rd.integer(j, "root", "obstacle_share_cap_percent", 1, 100, out.obstacle_share_cap_percent) ||
        !rd.integer(j, "root", "single_piece_keep_percent", 1, 100, out.single_piece_keep_percent)) return fail();
    const auto* sliver = rd.field(j, "root", "sliver");
    if (!sliver || !rd.keys(*sliver, "sliver", {"min_area_m2", "min_width_mm"}) ||
        !rd.integer(*sliver, "sliver", "min_area_m2", 0, 1000000, out.sliver_min_area_m2) ||
        !rd.integer(*sliver, "sliver", "min_width_mm", 0, 100000, out.sliver_min_width_mm)) return fail();
    const auto* simplify = rd.field(j, "root", "simplify");
    if (!simplify || !rd.keys(*simplify, "simplify", {"tolerance_mm"}) ||
        !rd.integer(*simplify, "simplify", "tolerance_mm", 0, 5000, out.simplify_tolerance_mm)) return fail();
    const auto* plausible = rd.field(j, "root", "plausible");
    if (!plausible || !rd.keys(*plausible, "plausible", {"min_area_m2", "max_area_m2", "min_width_mm"}) ||
        !rd.integer(*plausible, "plausible", "min_area_m2", 0, 1000000000, out.plausible_min_area_m2) ||
        !rd.integer(*plausible, "plausible", "max_area_m2", 1, 2000000000, out.plausible_max_area_m2) ||
        !rd.integer(*plausible, "plausible", "min_width_mm", 0, 1000000, out.plausible_min_width_mm)) return fail();
    if (out.plausible_min_area_m2 >= out.plausible_max_area_m2) { rd.fail("plausible.min_area_m2 must be below max_area_m2"); return fail(); }
    const auto* match = rd.field(j, "root", "match");
    if (!match || !rd.keys(*match, "match", {"max_anchor_distance_m"}) ||
        !rd.integer(*match, "match", "max_anchor_distance_m", 0, 5000, out.match_max_anchor_distance_m)) return fail();
    const auto* sources = rd.field(j, "root", "sources");
    if (!sources || !rd.object(*sources, "sources")) return fail();
    for (auto it = sources->begin(); it != sources->end(); ++it)
        if (!it.value().is_string()) { rd.fail("sources." + it.key() + " must be a string"); return fail(); }
    // The capsule of a splitter must stay inside the 128 m halo the OSM tiles are cut with.
    if (out.max_half_width_mm() > 100000) { rd.fail("splitter half width above 100 m"); return fail(); }
    out.content_sha256 = Sha256::of(bytes);
    return out;
}

std::span<const std::byte> builtin_field_rules_de_bytes() {
    return {reinterpret_cast<const std::byte*>(kFieldRulesDe), sizeof(kFieldRulesDe)};
}
const FieldRules& builtin_field_rules_de() {
    static const FieldRules rules = [] {
        auto loaded = load_field_rules(builtin_field_rules_de_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/field_rules/de.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return rules;
}
} // namespace g2m
